<?php
require __DIR__.'/bootstrap.php';
$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn(); $message='';
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){ check_csrf(); $name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];if(strlen($pass)<12)$message='Use a password with at least 12 characters.';else{$q=$pdo->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);header('Location: admin.php?created=1');exit;} }
site_header('Initial setup'); echo '<section class="hero"><span class="eyebrow">ONE TIME SETUP</span><h1>Create administrator</h1><p>This account manages campus content and feedback.</p></section>';if($count>0)echo '<div class="notice">An administrator already exists. <a href="admin.php">Go to sign in</a>.</div>';else{if($message)echo '<div class="notice error">'.h($message).'</div>';echo '<form class="panel form narrow" method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><label>Full name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required maxlength="190"></label><label>Password (12 characters minimum)<input name="password" type="password" minlength="12" required></label><button>Create administrator</button></form>';}site_footer();
